function settleNudge(text: string, state: TaskState, op: Op): string {
	// [pi-zh settle-nudge] F 线授权补丁：结算动作后仍有 in_progress 残留时，向模型追加提醒。
	// 回退分支：非结算动作或无残留时原样返回输入，行为与上游完全一致。
	const settled =
		op.kind === "delete" || (op.kind === "update" && (op.toStatus === "completed" || op.toStatus === "deleted"));
	if (!settled) return text;
	const unsettled = state.tasks.filter((task) => task.status === "in_progress");
	if (unsettled.length === 0) return text;
	const list = unsettled.map((task) => `#${task.id} ${sanitizeTerminalText(task.subject)}`).join(", ");
	return `${text}\nUnsettled: ${list} still in progress. Mark each one completed, move it back to pending, or delete it.`;
}

